import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// Hand-written in-process double for the downstream pricing service.
const prices = { apple: 10, pear: 25.5, gold: 101, hundred: 100 }
const pricing = { priceOf: async (sku) => prices[sku] }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const call = async (method, path, body, raw) => {
  const res = await fetch(base + path, {
    method,
    headers: body !== undefined || raw !== undefined ? { 'content-type': 'application/json' } : {},
    body: raw ?? (body === undefined ? undefined : JSON.stringify(body)),
  })
  return { status: res.status, type: res.headers.get('content-type'), body: await res.json() }
}
const create = (items) => call('POST', '/orders', { items })

test('POST /orders creates an order: 201, JSON, echoed items, string id, computed total', async () => {
  const r = await create([{ sku: 'apple', qty: 3 }])
  assert.equal(r.status, 201)
  assert.equal(r.type, 'application/json')
  assert.equal(typeof r.body.id, 'string')
  assert.deepEqual(r.body, { id: r.body.id, items: [{ sku: 'apple', qty: 3 }], total: 30 })
})

test('POST /orders ids increment sequentially', async () => {
  const a = await create([{ sku: 'apple', qty: 1 }])
  const b = await create([{ sku: 'apple', qty: 1 }])
  assert.equal(Number(b.body.id), Number(a.body.id) + 1)
})

test('POST /orders sums several lines and floors fractional totals', async () => {
  const r = await create([{ sku: 'pear', qty: 1 }, { sku: 'apple', qty: 1 }]) // 35.5
  assert.equal(r.body.total, 35)
})

test('POST /orders: total of exactly 100 gets no discount', async () => {
  assert.equal((await create([{ sku: 'hundred', qty: 1 }])).body.total, 100)
})

test('POST /orders: total above 100 gets 10% off, then floored', async () => {
  assert.equal((await create([{ sku: 'gold', qty: 1 }])).body.total, 90) // 90.9 -> 90
  assert.equal((await create([{ sku: 'apple', qty: 20 }])).body.total, 180) // 200 -> 180
})

test('POST /orders: missing qty yields a 201 with null total', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — qty is not validated; NaN serialises to null
  const r = await create([{ sku: 'apple' }])
  assert.equal(r.status, 201)
  assert.equal(r.body.total, null)
})

test('POST /orders: unknown sku (pricing returns undefined) yields 201 with null total', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — unpriced sku is not rejected
  const r = await create([{ sku: 'nope', qty: 1 }])
  assert.equal(r.status, 201)
  assert.equal(r.body.total, null)
})

for (const [name, body, raw] of [
  ['missing items', {}],
  ['empty items', { items: [] }],
  ['items not an array', { items: 'apple' }],
  ['empty body', undefined],
  ['invalid JSON', undefined, '{oops'],
  ['JSON null', undefined, 'null'],
]) {
  test(`POST /orders 400 for ${name}`, async () => {
    const r = await call('POST', '/orders', body, raw)
    assert.equal(r.status, 400)
    assert.equal(r.type, 'application/json')
    assert.deepEqual(r.body, { error: 'items required' })
  })
}

test('GET /orders/{id} returns the stored order', async () => {
  const created = await create([{ sku: 'apple', qty: 2 }])
  const r = await call('GET', `/orders/${created.body.id}`)
  assert.equal(r.status, 200)
  assert.equal(r.type, 'application/json')
  assert.deepEqual(r.body, created.body)
})

test('GET /orders/{id} for an unknown id returns 200 with an error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — "not found" is sent with status 200, not 404
  const r = await call('GET', '/orders/does-not-exist')
  assert.equal(r.status, 200)
  assert.deepEqual(r.body, { error: 'not found' })
})

test('unmatched routes return 404 "no route"', async () => {
  for (const [m, p] of [['GET', '/orders'], ['PUT', '/orders'], ['DELETE', '/orders/1'], ['POST', '/orders/1'], ['GET', '/orders/1/items'], ['GET', '/']]) {
    const r = await call(m, p)
    assert.equal(r.status, 404, `${m} ${p}`)
    assert.equal(r.type, 'application/json')
    assert.deepEqual(r.body, { error: 'no route' })
  }
})
EOF
